import{c as a,Q as s,j as i,m as t}from"./chunks/framework.BvWD_EvC.js";const n="/next/screenshots/admin-users.png",r="/next/screenshots/admin-backup.png",g=JSON.parse('{"title":"Administration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/using-librislog/administration.md","filePath":"guide/using-librislog/administration.md","lastUpdated":1793366331000}'),o={name:"guide/using-librislog/administration.md"};function l(h,e,d,p,c,u){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="administration" tabindex="-1">Administration <a class="header-anchor" href="#administration" aria-label="Permalink to &quot;Administration&quot;">​</a></h1><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>The administration page is available only to users with the <strong>admin</strong> role. Regular users cannot access it.</p></div><p><img src="'+n+'" alt="Users tab" loading="lazy"></p><h2 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h2><h3 id="creating-a-user" tabindex="-1">Creating a User <a class="header-anchor" href="#creating-a-user" aria-label="Permalink to &quot;Creating a User&quot;">​</a></h3><p>Admins can create new user accounts with either the <code>user</code> or <code>admin</code> role. The password must meet the complexity requirements displayed in the form.</p><h3 id="editing-a-user" tabindex="-1">Editing a User <a class="header-anchor" href="#editing-a-user" aria-label="Permalink to &quot;Editing a User&quot;">​</a></h3><p>Click &quot;Edit&quot; next to a user to change their name, email, password, or role. You cannot change your own admin role to prevent accidental lockout.</p><h3 id="deleting-a-user" tabindex="-1">Deleting a User <a class="header-anchor" href="#deleting-a-user" aria-label="Permalink to &quot;Deleting a User&quot;">​</a></h3><p>Click &quot;Delete&quot; to remove a user account. You cannot delete your own account from this page — use the <strong>Profile → Danger Zone</strong> instead.</p><h2 id="external-authentication" tabindex="-1">External Authentication <a class="header-anchor" href="#external-authentication" aria-label="Permalink to &quot;External Authentication&quot;">​</a></h2><p>LibrisLog can run with single sign-on (OIDC), trusted reverse-proxy authentication, or both. The methods are independent, so a deployment can keep password login as a fallback or turn it off entirely.</p><h3 id="disabling-password-login" tabindex="-1">Disabling Password Login <a class="header-anchor" href="#disabling-password-login" aria-label="Permalink to &quot;Disabling Password Login&quot;">​</a></h3><p>Set <code>PASSWORD_LOGIN_ENABLED=false</code> in the backend environment to hide the email/password form and &quot;Forgot password?&quot; link. <code>POST /api/auth/login</code>, <code>/api/auth/forgot-password</code>, and <code>/api/auth/reset-password</code> then return <code>403</code>. The first-admin setup remains available so a new instance can be bootstrapped.</p><p>Before disabling password login, make sure every user has linked their OIDC account: open <strong>Profile → Single Sign-On → Link account</strong>. Admin-created users without an OIDC link cannot sign in while password login is disabled. If you get locked out, set <code>PASSWORD_LOGIN_ENABLED=true</code> and restart the backend.</p><p>Set <code>OIDC_AUTO_REDIRECT=true</code> to send visitors straight to the provider instead of showing the login page. This only takes effect while password login is disabled; a failed attempt returns to the login page with the error instead of redirecting again.</p><p>For account management, admins can still create users and set passwords through <strong>Administration → Users</strong>. These actions do not enable password login while the flag is off; they only store the password for later use or recovery. The profile password field is hidden while password login is disabled.</p><h3 id="trusted-reverse-proxy-authentication" tabindex="-1">Trusted Reverse-Proxy Authentication <a class="header-anchor" href="#trusted-reverse-proxy-authentication" aria-label="Permalink to &quot;Trusted Reverse-Proxy Authentication&quot;">​</a></h3><p>With <code>TRUSTED_PROXY_AUTH_ENABLED=true</code>, LibrisLog trusts an HTTP header set by a reverse proxy such as Traefik BasicAuth and signs the matching user in automatically. See <a href="/next/guide/configuration.html#trusted-reverse-proxy-authentication-optional">Configuration → Trusted Reverse-Proxy Authentication</a> for the variables and a Traefik example.</p><p>Things to keep in mind:</p><ul><li>The forwarded value is matched against an existing user&#39;s email address (case-insensitive). Set <code>TRUSTED_PROXY_AUTH_USER_MAP</code> to translate proxy usernames to account emails, for example <code>alice=alice@example.com,bob=bob@example.com</code>. Values not present in the map are used as the email directly. Only rely on that fallback when the proxy controls the username and users cannot set it to arbitrary email addresses; otherwise map every allowed username. Unknown values are ignored; accounts are never created automatically.</li><li>Only requests from the configured <code>TRUSTED_PROXY_AUTH_IPS</code> are honored. Never expose the backend directly to clients that could spoof the header.</li><li>When Uvicorn&#39;s proxy-header handling rewrites the connecting address from <code>X-Forwarded-For</code>, set <code>TRUSTED_PROXY_AUTH_SECRET</code> and have the proxy inject it, or restrict <code>FORWARDED_ALLOW_IPS</code> to the proxy only. Other containers on the same Docker network can present the header, so the secret is recommended there too.</li><li>Because the proxy owns authentication, logging out of LibrisLog does not end the proxy session. The next request signs the user back in. Use the proxy&#39;s logout to switch users.</li><li>On a shared browser, a change of proxy user replaces the LibrisLog session with the new user on the next request.</li></ul><h2 id="backup-restore" tabindex="-1">Backup &amp; Restore <a class="header-anchor" href="#backup-restore" aria-label="Permalink to &quot;Backup &amp; Restore&quot;">​</a></h2><p><img src="'+r+`" alt="Backup and Restore tab" loading="lazy"></p><h3 id="creating-a-backup" tabindex="-1">Creating a Backup <a class="header-anchor" href="#creating-a-backup" aria-label="Permalink to &quot;Creating a Backup&quot;">​</a></h3><p>Downloads a ZIP archive containing the SQLite database, cover images, and import temp files. This is a complete snapshot of your library, users, and settings.</p><h3 id="restoring-a-backup" tabindex="-1">Restoring a Backup <a class="header-anchor" href="#restoring-a-backup" aria-label="Permalink to &quot;Restoring a Backup&quot;">​</a></h3><p>Upload a previously downloaded <code>.zip</code> backup file to restore the database. The app validates the backup before applying it. Backups from older versions are automatically migrated to the current schema on restore.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Restoring overwrites all current data. Create a fresh backup first if you want to preserve your current library.</p></div><h3 id="automating-backups" tabindex="-1">Automating Backups <a class="header-anchor" href="#automating-backups" aria-label="Permalink to &quot;Automating Backups&quot;">​</a></h3><p>The backup endpoint is accessible via the REST API, making it easy to automate with cron (or any scheduler).</p><p>First, <a href="/next/api/#creating-an-api-key">create an API key</a> with the admin user. Then use it in a cron script:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/usr/bin/env bash</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Save as /etc/cron.daily/librislog-backup or add to crontab</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lsk_your-key-here&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:8000/api/admin/backup&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/var/backups/librislog&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DEST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-API-Key: </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DEST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/librislog-$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%F).zip&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Keep only the last 30 backups</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DEST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;librislog-*.zip&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -mtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +30</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -delete</span></span></code></pre></div><p>Crontab entry (daily at 3am):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0 3 * * * /path/to/backup-script.sh</span></span></code></pre></div><p>The API returns a ZIP archive containing the SQLite database, cover images, and import temp files. No separate database dump step is needed.</p><h2 id="background-maintenance" tabindex="-1">Background Maintenance <a class="header-anchor" href="#background-maintenance" aria-label="Permalink to &quot;Background Maintenance&quot;">​</a></h2><p>A periodic maintenance task runs automatically every hour. It performs:</p><ul><li><strong>Cover cache cleanup</strong> — Removes orphaned cover images from disk that are no longer referenced by any book. Files modified within the last 60 minutes are preserved to avoid deleting covers that were just uploaded but not yet linked to a book entry.</li></ul>`,38)])])}const m=a(o,[["render",l]]);export{g as __pageData,m as default};
